/* legacy_logger.c - Syslog forwarding daemon for internal metrics
 * Compiled with: gcc -o legacy_logger legacy_logger.c -no-pie -fno-stack-protector
 * Runs as: ./legacy_logger <port>
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_MSG 512
#define LOG_FILE "/var/log/metrics.log"

static char admin_token[64] = "INTERNAL_METRICS_TOKEN_2019";

void log_message(const char *client_ip, const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fp = fopen("/tmp/metrics_fallback.log", "a");
        if (!fp) return;
    }

    time_t now = time(NULL);
    char timebuf[64];
    strftime(timebuf, sizeof(timebuf), "%Y-%m-%d %H:%M:%S", localtime(&now));

    /* Log the raw message with timestamp and source */
    fprintf(fp, "[%s] from %s: ", timebuf, client_ip);
    fprintf(fp, message);  /* VULNERABILITY: format string from user input */
    fprintf(fp, "\n");
    fclose(fp);
}

void send_response(int client_fd, const char *status, const char *body) {
    char response[1024];
    snprintf(response, sizeof(response),
        "HTTP/1.0 %s\r\nContent-Length: %zu\r\n\r\n%s",
        status, strlen(body), body);
    write(client_fd, response, strlen(response));
}

void handle_client(int client_fd, struct sockaddr_in *client_addr) {
    char buffer[MAX_MSG];
    char client_ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &client_addr->sin_addr, client_ip, sizeof(client_ip));

    ssize_t n = read(client_fd, buffer, MAX_MSG - 1);
    if (n <= 0) { close(client_fd); return; }
    buffer[n] = '\0';

    /* Parse simple HTTP POST body for metric data */
    char *body = strstr(buffer, "\r\n\r\n");
    if (!body) {
        send_response(client_fd, "400 Bad Request", "Missing body");
        close(client_fd);
        return;
    }
    body += 4;

    /* Basic auth check - token in X-Metrics-Token header */
    char *token_hdr = strstr(buffer, "X-Metrics-Token: ");
    if (!token_hdr) {
        send_response(client_fd, "401 Unauthorized", "Token required");
        close(client_fd);
        return;
    }

    char provided_token[64] = {0};
    sscanf(token_hdr + 17, "%63[^\r\n]", provided_token);
    if (strncmp(provided_token, admin_token, strlen(admin_token)) != 0) {
        send_response(client_fd, "403 Forbidden", "Invalid token");
        close(client_fd);
        return;
    }

    log_message(client_ip, body);
    send_response(client_fd, "200 OK", "Logged");
    close(client_fd);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <port>\n", argv[0]);
        return 1;
    }

    int port = atoi(argv[1]);
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = { .sin_family = AF_INET, .sin_port = htons(port), .sin_addr.s_addr = INADDR_ANY };
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 10);

    printf("[*] Metrics logger listening on port %d\n", port);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &len);
        if (client_fd < 0) continue;
        handle_client(client_fd, &client_addr);
    }
    return 0;
}
